/**
 * shims.js
 * Writes the agent shims (bash scripts named claude, codex, opencode) that MeuTerminal puts
 * first on its shells' PATH, so typing an agent can offer the agent UI before running it.
 */
const fs = require('fs');
const path = require('path');

const CLIENT = path.join(__dirname, 'launch-client.js');

/**
 * The shim finds the real binary on PATH (skipping its own folder), asks the server only for
 * interactive terminals, and otherwise execs the real binary exactly as typed.
 */
function shimScript(agent, nodePath) {
    return `#!/usr/bin/env bash
# Generated by MeuTerminal (scripts/agents/shims.js). Offers the agent UI for "${agent}".
# MT_NO_INTERCEPT=1 disables it; scripts, pipes and CI (no TTY) are never intercepted.
shim_dir="$(cd "$(dirname "\${BASH_SOURCE[0]}")" && pwd)"
real=""
IFS=':' read -r -a path_dirs <<< "$PATH"
for dir in "\${path_dirs[@]}"; do
    [ -z "$dir" ] && continue
    [ "$(cd "$dir" 2>/dev/null && pwd)" = "$shim_dir" ] && continue
    if [ -x "$dir/${agent}" ] && [ ! -d "$dir/${agent}" ]; then real="$dir/${agent}"; break; fi
done
if [ -z "$real" ]; then
    echo "${agent}: command not found" >&2
    exit 127
fi
if [ -z "\${MT_NO_INTERCEPT:-}" ] && [ -t 0 ] && [ -t 1 ] && [ -n "\${MEUTERMINAL_API_URL:-}" ]; then
    if "${nodePath}" "${CLIENT}" ${agent} "$@"; then exit 0; fi
fi
exec "$real" "$@"
`;
}

/**
 * (Re)writes one shim per UI-capable agent into `dir` and removes shims of agents no longer
 * offered. Returns the folder to prepend to PATH.
 * @param {string} dir
 * @param {string[]} agents - registry ids (terminal-only agents excluded by the caller)
 * @param {{ nodePath?: string }} [opts]
 */
function writeShims(dir, agents, { nodePath = process.execPath } = {}) {
    fs.mkdirSync(dir, { recursive: true });
    for (const name of fs.readdirSync(dir)) {
        const file = path.join(dir, name);
        let ours = false;
        try { ours = fs.statSync(file).isFile() && fs.readFileSync(file, 'utf8').includes('Generated by MeuTerminal'); } catch { /* unreadable: not ours */ }
        if (ours && !agents.includes(name)) fs.rmSync(file);
    }
    for (const agent of agents) {
        const file = path.join(dir, agent);
        fs.writeFileSync(file, shimScript(agent, nodePath), { mode: 0o755 });
        fs.chmodSync(file, 0o755);
    }
    return dir;
}

module.exports = { writeShims, shimScript };
